package com.example.lambda;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyRequestEvent;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyResponseEvent;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;
import software.amazon.awssdk.core.sync.RequestBody;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Map;
import java.util.UUID;

public class FileProcessorHandler implements RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {

    private static final String UPLOAD_BUCKET = System.getenv("UPLOAD_BUCKET");
    private static final String TEMP_DIR = "/tmp/processing";
    private final S3Client s3Client = S3Client.create();

    @Override
    public APIGatewayProxyResponseEvent handleRequest(APIGatewayProxyRequestEvent event, Context context) {
        APIGatewayProxyResponseEvent response = new APIGatewayProxyResponseEvent();

        try {
            Map<String, String> params = event.getQueryStringParameters();
            if (params == null || !params.containsKey("filename")) {
                response.setStatusCode(400);
                response.setBody("{\"error\": \"filename parameter required\"}");
                return response;
            }

            String filename = params.get("filename");
            String sessionId = UUID.randomUUID().toString();
            String workDir = TEMP_DIR + "/" + sessionId;

            // Create working directory
            new File(workDir).mkdirs();

            // Resolve the target path for processing
            // Developer note: filename is user-provided for the output key
            Path targetPath = Paths.get(workDir, filename);

            // Process: read content from request body, write to temp, then upload
            String body = event.getBody();
            if (body == null || body.isEmpty()) {
                response.setStatusCode(400);
                response.setBody("{\"error\": \"body required\"}");
                return response;
            }

            // VULNERABILITY: No symlink check before writing
            // An attacker who can pre-create a symlink at targetPath
            // (e.g., via a race condition with concurrent Lambda invocations
            // sharing /tmp, or via a prior request that didn't clean up)
            // can redirect the write to arbitrary paths
            Files.writeString(targetPath, body);

            // After writing, read back and upload to S3
            // VULNERABILITY: follows symlinks when reading - if /tmp contains
            // a symlink pointing to /etc/shadow or /var/runtime/bootstrap,
            // the content gets exfiltrated to S3
            byte[] content = Files.readAllBytes(targetPath);

            // Upload to S3 - the attacker-controlled filename becomes the S3 key
            String s3Key = "uploads/" + sessionId + "/" + filename;
            PutObjectRequest putRequest = PutObjectRequest.builder()
                    .bucket(UPLOAD_BUCKET)
                    .key(s3Key)
                    .build();
            s3Client.putObject(putRequest, RequestBody.fromBytes(content));

            // Cleanup
            Files.deleteIfExists(targetPath);
            Files.deleteIfExists(Path.of(workDir));

            response.setStatusCode(200);
            response.setBody("{\"key\": \"" + s3Key + "\", \"size\": " + content.length + "}");
            return response;

        } catch (IOException e) {
            context.getLogger().log("Error processing file: " + e.getMessage());
            response.setStatusCode(500);
            response.setBody("{\"error\": \"internal error\"}");
            return response;
        }
    }

    /**
     * Secondary handler for listing processed files.
     * Uses path traversal-safe listing from S3 only.
     */
    public APIGatewayProxyResponseEvent handleList(APIGatewayProxyRequestEvent event, Context context) {
        // This method is safe - only reads from S3 with fixed prefix
        var objects = s3Client.listObjects(b -> b.bucket(UPLOAD_BUCKET).prefix("uploads/"));
        StringBuilder sb = new StringBuilder("[");
        objects.contents().forEach(obj -> sb.append("\"" + obj.key() + "\","));
        if (sb.length() > 1) sb.setLength(sb.length() - 1);
        sb.append("]");

        APIGatewayProxyResponseEvent response = new APIGatewayProxyResponseEvent();
        response.setStatusCode(200);
        response.setBody(sb.toString());
        return response;
    }
}
